import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState } from '../store/store';
import { toggleConfig } from '../store/schedulerSlice';
import { OptimizationConfig } from '../types';

interface OptimizationControlsProps {
  onResetCounters: () => void;
}

export const OptimizationControls: React.FC<OptimizationControlsProps> = ({
  onResetCounters
}) => {
  const dispatch = useDispatch();
  const config = useSelector((state: RootState) => state.scheduler.config);

  const handleToggle = (key: keyof OptimizationConfig) => {
    dispatch(toggleConfig(key));
  };

  return (
    <div className="controls-card">
      <div className="toggles-grid">
        <div>
          <div className="toggle-label-wrap" onClick={() => handleToggle('useMemoCards')}>
            <div className={`toggle-switch ${config.useMemoCards ? 'active' : ''}`}>
              <div className="toggle-knob" />
            </div>
            <span className="toggle-title">React.memo on cards</span>
          </div>
          <p className="toggle-desc">
            Skip a card's re-render when its own props haven't changed.
          </p>
        </div>

        <div>
          <div className="toggle-label-wrap" onClick={() => handleToggle('useCallbackHandlers')}>
            <div className={`toggle-switch ${config.useCallbackHandlers ? 'active' : ''}`}>
              <div className="toggle-knob" />
            </div>
            <span className="toggle-title">useCallback for handlers</span>
          </div>
          <p className="toggle-desc">
            Keep drag handlers referentially stable so memo isn't fooled.
          </p>
        </div>

        <div>
          <div className="toggle-label-wrap" onClick={() => handleToggle('useMemoFilter')}>
            <div className={`toggle-switch ${config.useMemoFilter ? 'active' : ''}`}>
              <div className="toggle-knob" />
            </div>
            <span className="toggle-title">useMemo for agenda filter</span>
          </div>
          <p className="toggle-desc">
            Cache the filtered list; recompute only when events or day change.
          </p>
        </div>
      </div>

      <div className="toggle-row">
        <div>
          <div className="toggle-label-wrap" onClick={() => handleToggle('liveClock')}>
            <div className={`toggle-switch ${config.liveClock ? 'active' : ''}`}>
              <div className="toggle-knob" />
            </div>
            <span className="toggle-title">Live clock</span>
          </div>
          <p className="toggle-desc">
            Ticks every 450ms to simulate unrelated state elsewhere in the app.
          </p>
        </div>
        <button className="btn-reset" onClick={onResetCounters}>
          Reset counters
        </button>
      </div>
    </div>
  );
};
